package com.bankingax.task.b02; import com.bankingax.core.api.*; import com.bankingax.core.tool.*; import com.bankingax.core.verification.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/b02") public class B02Controller {final B02Service s;final InternalGatewayAuthenticator a; B02Controller(B02Service s,InternalGatewayAuthenticator a){this.s=s;this.a=a;} void ok(long actor,ActorRole role,String token,long customer){a.verify(token);if(role!=ActorRole.CUSTOMER||actor!=customer)throw new DomainException("FORBIDDEN","Customer ownership cannot be verified.");}
 @PostMapping("/prepare") ApiEnvelope<B02Service.P> p(@RequestHeader("X-Actor-Id")long x,@RequestHeader("X-Actor-Role")ActorRole r,@RequestHeader("X-Tool-Gateway-Token")String t,@RequestBody Q q){ok(x,r,t,q.customer);return ApiEnvelope.success(q.requestId,"HOUSING_SAVINGS_CLOSE",null,null,null,s.prepare(q.customer,q.account,q.waive,q.taxed));}
 @PostMapping("/{id}/otp") ApiEnvelope<VerificationIssue> i(@PathVariable("id") long id,@RequestHeader("X-Actor-Id")long x,@RequestHeader("X-Actor-Role")ActorRole r,@RequestHeader("X-Tool-Gateway-Token")String t,@RequestBody O q){ok(x,r,t,q.customer);return ApiEnvelope.success(q.requestId,"HOUSING_SAVINGS_CLOSE",id,null,q.version,s.issue(q.customer,id,q.version,q.consent,q.signed,q.phone));}
 @PostMapping("/otp/verify") ApiEnvelope<VerificationBinding> v(@RequestHeader("X-Actor-Id")long x,@RequestHeader("X-Actor-Role")ActorRole r,@RequestHeader("X-Tool-Gateway-Token")String t,@RequestBody V q){ok(x,r,t,q.customer);return ApiEnvelope.success(q.requestId,"HOUSING_SAVINGS_CLOSE",null,null,null,s.verify(q.customer,q.challenge,q.otp));}
 @PostMapping("/{id}/execute") ApiEnvelope<B02Service.R> e(@PathVariable("id") long id,@RequestHeader("X-Actor-Id")long x,@RequestHeader("X-Actor-Role")ActorRole r,@RequestHeader("X-Tool-Gateway-Token")String t,@RequestBody E q){ok(x,r,t,q.customer);return ApiEnvelope.success(q.requestId,"HOUSING_SAVINGS_CLOSE",id,null,q.version,s.execute(new B02Service.C(q.requestId,q.customer,id,q.version,q.waive,q.taxed,q.binding)));}
 public record Q(String requestId,long customer,long account,boolean waive,Boolean taxed){} public record O(String requestId,long customer,int version,boolean consent,boolean signed,String phone){} public record V(String requestId,long customer,String challenge,String otp){} public record E(String requestId,long customer,int version,boolean waive,Boolean taxed,String binding){}
}
